DG.put("krisnaavtaar/66",{"n":66,"title":"ਅਥ ਰੁਕਮਿਨਿ ਬ੍ਯਾਹ ਕਥਨੰ","title_roman":"Ath rukmini byaah kathnan","page":641,"blocks":[{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":641,"meaning_status":"draft"},{"type":"verse","number":[1968],"number_text":"੧੯੬੮।","page":641,"lines":[{"gurmukhi":"ਬਲਿਰਾਮ ਕੋ ਬ੍ਯਾਹ ਭਯੋ ਜਬ ਹੀ ਮਿਲਿ ਕੈ ਨਰ ਨਾਰਿ ਤਬੈ ਸੁਖੁ ਪਾਯੋ।","roman":"Baliraam ko byaah bhayo jab hee mili kai nar naari tabai sukhu paayo |","meaning_en":"When Balram's marriage had taken place, men and women together were happy.","page":641,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰੀ ਬ੍ਰਿਜਨਾਥ ਕੇ ਬ੍ਯਾਹ ਕੋ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਜੀਅਰਾ ਲਲਚਾਯੋ।","roman":"Sree brijnaath ke byaah ko kabi syaam kahai jeearaa lalchaayo |","meaning_en":"Poet Shyam says, then hearts longed for the marriage of the Lord of Braj.","page":641,"meaning_status":"draft"},{"gurmukhi":"ਭੀਖਮ ਬ੍ਯਾਹ ਉਤੇ ਦੁਹਤਾ ਕੋ ਰਚਿਓ ਅਪਨੋ ਸਭ ਸੈਨ ਬੁਲਾਯੋ।","roman":"Bheekham byaah ute duhtaa ko rachio apno sabh sain bulaayo |","meaning_en":"Over there, Bhikham arranged his daughter's wedding and called in all his army,","page":642,"meaning_status":"draft","note":"ਭੀਖਮ: King Bhikham (Rukmini's father)."},{"gurmukhi":"ਮਾਨਹੁ ਆਪਨੇ ਬ੍ਯਾਹਹਿ ਕੋ ਜਦੁਬੀਰ ਭਲੀ ਬਿਧਿ ਬ੍ਯੋਤ ਬਨਾਯੋ। ੧੯੬੮।","roman":"Maanhu aapne byaahhi ko jadubeer bhalee bidhi byot banaayo | 1968 |","meaning_en":"as though the Yadav hero had himself made fine arrangements for his own wedding.","page":642,"meaning_status":"draft"}]},{"type":"verse","number":[1969],"number_text":"੧੯੬੯।","page":642,"lines":[{"gurmukhi":"ਭੀਖਮ ਭੂਪ ਬਿਚਾਰ ਕੀਯੋ ਦੁਹਤਾ ਇਹ ਸ੍ਰੀ ਜਦੁਬੀਰ ਕੋ ਦੀਜੈ।","roman":"Bheekham bhoop bichaar keeyo duhtaa ih sree jadubeer ko deejai |","meaning_en":"King Bhikham thought: 'This daughter should be given to the Yadav hero.'","page":642,"meaning_status":"draft"},{"gurmukhi":"ਯਾ ਤੇ ਭਲੋ ਨ ਕਛੂ ਕਹੂੰ ਹੈ ਹਮ ਸ੍ਯਾਮ ਲਹੈ ਜਗ ਮੈ ਜਸੁ ਲੀਜੈ।","roman":"Yaa te bhalo na kachhoo kahoon hai ham syaam lahai jag mai jasu leejai |","meaning_en":"'Nothing anywhere is better than this; let us gain Shyam and win praise in the world.'","page":642,"meaning_status":"draft"},{"gurmukhi":"ਤਉ ਲਗਿ ਆਇ ਗਯੋ ਰੁਕਮੀ ਰਿਸਿ ਬੋਲ ਉਠਿਯੋ ਸੁ ਪਿਤਾ ਕਸ ਕੀਜੈ।","roman":"Tau lagi aai gayo rukmee risi bol uthiyo su pitaa kas keejai |","meaning_en":"Meanwhile Rukmi came and spoke up in anger: 'Father, why should this be done?'","page":642,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਕੁਲ ਕੀ ਨ ਬਿਵਾਹਤ ਹੈ ਹਮ ਤਾ ਦੁਹਿਤਾ ਦੈ ਕਹਾ ਜਗੁ ਜੀਜੈ। ੧੯੬੯।","roman":"Jaa kul kee na bivaahat hai ham taa duhitaa dai kahaa jagu jeejai | 1969 |","meaning_en":"'If we give our daughter to a clan we do not marry with, how shall we live in the world?'","page":642,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਰਕਮੀ ਬਾਚ ‘ਨ੍ਰਿਪ ਸੋ","gurmukhi":"ਰਕਮੀ ਬਾਚ ‘ਨ੍ਰਿਪ ਸੋ","roman":"Rakmee baach ‘nrip so","meaning_en":"Rukmi said to the king:","page":642,"meaning_status":"draft","note":"Printed ਰਕਮੀ (read as ਰੁਕਮੀ, Rukmi), with a stray opening quotation mark before ਨ੍ਰਿਪ; text left as printed."},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":642,"meaning_status":"draft"},{"type":"verse","number":[1970],"number_text":"੧੯੭੦।","page":642,"lines":[{"gurmukhi":"ਹੈ ਸਿਸੁਪਾਲ ਚੰਦੇਰੀ ਮੈ ਬੀਰ ਸੁ ਤਾਹਿ ਬਿਯਾਹ ਕੇ ਕਾਜ ਬੁਲਈਯੈ।","roman":"Hai sisupaal chanderee mai beer su taahi biyaah ke kaaj bulaeeyai |","meaning_en":"'There is Shishupal, a warrior in Chanderi; let him be invited for the wedding.'","page":642,"meaning_status":"draft"},{"gurmukhi":"ਗੂਜਰ ਕੋ ਕਹਿਯੋ ਦੈ ਦੁਹਿਤਾ ਜਗ ਮੈ ਸੰਗ ਲਾਜਨ ਕੇ ਮਰਿ ਜਈਯੈ।","roman":"Goojar ko kahiyo dai duhitaa jag mai sang laajan ke mari jaeeyai |","meaning_en":"'If we give our daughter to a cowherd, we should die of shame in the world.'","page":642,"meaning_status":"draft","note":"ਗੂਜਰ: 'cowherd (Gujar)', a slight on Krishna."},{"gurmukhi":"ਸ੍ਰੇਸਟ ਏਕ ਬੁਲਾਇ ਭਲੋ ਦਿਜ ਤਾਹੀ ਕੇ ਲਿਆਵਨ ਕਾਜ ਪਠਈਯੈ।","roman":"Sresat ek bulaai bhalo dij taahee ke liaavan kaaj pathaeeyai |","meaning_en":"'Call one good and excellent Brahmin and send him to bring him.'","page":642,"meaning_status":"draft"},{"gurmukhi":"ਬ੍ਯਾਹ ਕੀ ਜੋ ਬਿਧਿ ਬੇਦ ਲਿਖੀ ਦੁਹਿਤਾ ਸੋਊ ਕੈ ਬਿਧਿ ਤਾਹਿ ਕਉ ਦਈਯੈ। ੧੯੭੦।","roman":"Byaah kee jo bidhi bed likhee duhitaa so'oo kai bidhi taahi kau daeeyai | 1970 |","meaning_en":"'Whatever rite of marriage the Vedas lay down, by that rite give the daughter to him.'","page":642,"meaning_status":"draft"}]},{"type":"verse","number":[1971],"number_text":"੧੯੭੧।","page":642,"lines":[{"gurmukhi":"ਯੌ ਸੁਨਿ ਕੈ ਸੁਤ ਕੀ ਬਤੀਯਾ ਨ੍ਰਿਪ ਬਾਮਨ ਤਾਹੀ ਕੋ ਲੈਨ ਪਠਾਯੋ।","roman":"Yau suni kai sut kee bateeyaa nrip baaman taahee ko lain pathaayo |","meaning_en":"Hearing his son's words thus, the king sent a Brahmin to fetch him.","page":642,"meaning_status":"draft"},{"gurmukhi":"ਦੈ ਦਿਜ ਸੀਸ ਚਲਿਓ ਉਤ ਕੋ ਦੁਹਿਤਾ ਇਤ ਭੂਪਤਿ ਕੀ ਸੁਨਿ ਪਾਯੋ।","roman":"Dai dij sees chalio ut ko duhitaa it bhoopti kee suni paayo |","meaning_en":"Giving his blessing, the Brahmin set off there; here the king's daughter heard of it.","page":642,"meaning_status":"draft","note":"ਦੈ ਦਿਜ ਸੀਸ: read as 'the Brahmin giving blessing'; possibly 'bowing his head'; uncertain."},{"gurmukhi":"ਸੀਸ ਧੁਨੈ ਕਬ ਸ੍ਯਾਮ ਭਨੈ ਤਿਨਿ ਨੈਨਨ ਤੇ ਅਤਿ ਨੀਰ ਬਹਾਯੋ।","roman":"Sees dhunai kab syaam bhanai tini nainan te ati neer bahaayo |","meaning_en":"She beat her head, says poet Shyam, and shed many tears from her eyes,","page":642,"meaning_status":"draft"},{"gurmukhi":"ਮਾਨਹੁ ਆਸਹਿ ਕੀ ਕਟਿਗੀ ਜਰ ਸੁੰਦਰ ਰੂਖ ਸੁ ਹੈ ਮੁਰਝਾਯੋ। ੧੯੭੧।","roman":"Maanhu aashi kee katigee jar sundar rookh su hai murjhaayo | 1971 |","meaning_en":"as though the root of hope had been cut and a beautiful tree had withered.","page":642,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਰੁਕਮਿਨੀ ਬਾਚ ਸਖੀਅਨ ਸੋ","gurmukhi":"ਰੁਕਮਿਨੀ ਬਾਚ ਸਖੀਅਨ ਸੋ","roman":"Rukminee baach sakheean so","meaning_en":"Rukmini said to her companions:","page":642,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":642,"meaning_status":"draft"},{"type":"verse","number":[1972],"number_text":"੧੯੭੨।","page":642,"lines":[{"gurmukhi":"ਸੰਗ ਸਹੇਲਿਨ ਬੋਲਤ ਭੀ ਸਜਨੀ ਪ੍ਰਨ ਏਕ ਅਬੈ ਕਰਿ ਹਉ।","roman":"Sang sahelin bolat bhee sajnee pran ek abai kari hau |","meaning_en":"She spoke to her companions: 'O friend, I shall now make a vow:'","page":642,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੋ ਜੋਗਨਿ ਭੇਸ ਕਰੋ ਤਜ ਦੇਸ ਨਹੀ ਬਿਰਹਾਗਿਨ ਸੋ ਜਰਿ ਹਉ।","roman":"Kito jogni bhes karo taj des nahee birhaagin so jari hau |","meaning_en":"'either I shall put on a yogini's garb and leave the country, or else I shall burn in the fire of separation.'","page":642,"meaning_status":"draft","note":"ਨਹੀ taken as 'or else'; uncertain."},{"gurmukhi":"ਮੋਰ ਪਿਤਾ ਹਠ ਜਿਉ ਕਰ ਹੈ ਤੁ ਬਿਸੇਖ ਕਹਿਓ ਬਿਖ ਖਾ ਮਰਿ ਹਉ।","roman":"Mor pitaa hath jiu kar hai tu bisekh kahio bikh khaa mari hau |","meaning_en":"'If my father persists in his stubbornness, then, I tell you plainly, I shall eat poison and die.'","page":642,"meaning_status":"draft","note":"ਬਿਸੇਖ: 'especially / plainly'."},{"gurmukhi":"ਦੁਹਿਤਾ ਨ੍ਰਿਪ ਕੀ ਕਹਿਓ ਨ ਤਿਹ ਕਉ ਬਰਿ ਹੌ ਤੁ ਸ੍ਯਾਮ ਹੀ ਕੋ ਬਰਿ ਹਉ। ੧੯੭੨।","roman":"Duhitaa nrip kee kahio na tih kau bari hau tu syaam hee ko bari hau | 1972 |","meaning_en":"The king's daughter said, 'I shall not marry him; I shall marry Shyam alone.'","page":642,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":642,"meaning_status":"draft"},{"type":"verse","number":[1973],"number_text":"੧੯੭੩।","page":642,"lines":[{"gurmukhi":"ਅਉਰ ਬਿਚਾਰੀ ਮਨ ਬਿਖੈ ਕਰਿ ਹੋ ਏਕ ਉਪਾਇ।","roman":"Aur bichaaree man bikhai kari ho ek upaai |","meaning_en":"She thought further in her mind: 'I shall try one means:'","page":642,"meaning_status":"draft"},{"gurmukhi":"ਪਤੀਆ ਦੈ ਕੋਊ ਭੇਜ ਹੋ ਪ੍ਰਭ ਦੈ ਹੈ ਸੁਧਿ ਜਾਇ। ੧੯੭੩।","roman":"Pateeaa dai ko'oo bhej ho prabh dai hai sudhi jaai | 1973 |","meaning_en":"'I shall send a letter by someone, who will go and give the Lord word of it.'","page":642,"meaning_status":"draft"}]},{"type":"verse","number":[1974],"number_text":"੧੯੭੪।","page":642,"lines":[{"gurmukhi":"ਇਹ ਚਿੰਤਾ ਕਰਿ ਚਿਤ ਬਿਖੈ ਇਕ ਦਿਜ ਲਯੋ ਬੁਲਾਇ।","roman":"Ih chintaa kari chit bikhai ik dij layo bulaai |","meaning_en":"With this concern in her heart, she called a Brahmin.","page":642,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁ ਧਨੁ ਦੈ ਤਾ ਕੋ ਕਹਿਓ ਪ੍ਰਭ ਦੇ ਪਤੀਆ ਜਾਇ। ੧੯੭੪।","roman":"Bahu dhanu dai taa ko kahio prabh de pateeaa jaai | 1974 |","meaning_en":"Giving him much wealth, she said, 'Go and give this letter to the Lord.'","page":642,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਰੁਕਮਿਨੀ ਪਾਤੀ ਪਠੀ ਕਾਨ੍ਹ ਪ੍ਰਤਿ","gurmukhi":"ਰੁਕਮਿਨੀ ਪਾਤੀ ਪਠੀ ਕਾਨ੍ਹ ਪ੍ਰਤਿ","roman":"Rukminee paatee pathee kaanh prati","meaning_en":"Rukmini sent a letter to Krishna:","page":643,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":643,"meaning_status":"draft"},{"type":"verse","number":[1975],"number_text":"੧੯੭੫।","page":643,"lines":[{"gurmukhi":"ਲੋਚਨ ਚਾਰੁ ਬਿਚਾਰ ਕਰੋ ਜਿਨਿ ਬਾਚਤ ਹੀ ਪਤੀਆ ਉਠਿ ਧਾਵਹੁ।","roman":"Lochan chaaru bichaar karo jini baachat hee pateeaa uthi dhaavhu |","meaning_en":"'O lovely-eyed one, do not stop to think; as soon as you read this letter, rise and hasten.'","page":643,"meaning_status":"draft","note":"ਲੋਚਨ ਚਾਰੁ: 'beautiful-eyed', taken as addressing Krishna."},{"gurmukhi":"ਆਵਤ ਹੈ ਸਿਸਪਾਲ ਇਤੈ ਮੁਹਿ ਬ੍ਯਾਹਨ ਕਉ ਪ੍ਰਭ ਢੀਲ ਨ ਲਾਵਹੁ।","roman":"Aavat hai sispaal itai muhi byaahan kau prabh dheel na laavhu |","meaning_en":"'Shishupal is coming here to marry me; Lord, do not delay.'","page":643,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰਿ ਇਨੈ ਮੁਹਿ ਜੀਤਿ ਪ੍ਰਭੂ ਚਲੋ ਦ੍ਵਾਰਵਤੀ ਜਗ ਮੈ ਜਸੁ ਪਾਵਹੁ।","roman":"Maari inai muhi jeeti prabhoo chalo dvaaravtee jag mai jasu paavhu |","meaning_en":"'Slay these, win me, Lord, and go to Dwarvati; gain glory in the world.'","page":643,"meaning_status":"draft"},{"gurmukhi":"ਮੋਰੀ ਦਸਾ ਸੁਨਿ ਕੈ ਸਭ ਯੌ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਕਰਿ ਪੰਖਨ ਆਵਹੁ। ੧੯੭੫।","roman":"Moree dasaa suni kai sabh yau kabi syaam kahai kari pankhan aavhu | 1975 |","meaning_en":"'Having heard all my plight thus, says poet Shyam, come as if on wings.'","page":643,"meaning_status":"draft"}]},{"type":"verse","number":[1976],"number_text":"੧੯੭੬।","page":643,"lines":[{"gurmukhi":"ਹੇ ਪਤਿ ਚਉਦਹਿ ਲੋਕਨ ਕੇ ਸੁਨੀਐ ਚਿਤ ਦੈ ਜੁ ਸੰਦੇਸ ਕਹੇ ਹੈ।","roman":"He pati chaudhi lokan ke suneeai chit dai ju sandes kahe hai |","meaning_en":"'O Lord of the fourteen worlds, listen attentively to the message I send:'","page":643,"meaning_status":"draft"},{"gurmukhi":"ਤੇਰੇ ਬਿਨਾ ਸੁ ਅਹੰ ਅਰੁ ਕ੍ਰੋਧੁ ਬਢਿਓ ਸਭ ਆਤਮੇ ਤੀਨ ਬਹੇ ਹੈ।","roman":"Tere binaa su ahan aru krodhu badhio sabh aatme teen bahe hai |","meaning_en":"'without you, pride and anger have grown, and all three have swept over my soul.'","page":643,"meaning_status":"draft","note":"ਸਭ ਆਤਮੇ ਤੀਨ ਬਹੇ ਹੈ: unclear; 'three' perhaps the three qualities (gunas) or three torments; uncertain."},{"gurmukhi":"ਯੌ ਸੁਨੀਐ ਤਿਪੁਰਾਰਿ ਤੇ ਆਦਿਕ ਚਿਤ ਬਿਖੈ ਕਬ ਹੂੰ ਨ ਚਹੇ ਹੈ।","roman":"Yau suneeai tipuraari te aadik chit bikhai kab hoon na chahe hai |","meaning_en":"'Hear this: Shiva (Tripurari) and the others I have never desired in my mind.'","page":643,"meaning_status":"draft","note":"Read as Rukmini saying she never wished for anyone else; uncertain."},{"gurmukhi":"ਬਾਚਤ ਹੀ ਪਤੀਯਾ ਉਠਿ ਆਵਹੁ ਜੂ ਬ੍ਯਾਹ ਬਿਖੈ ਦਿਨ ਤੀਨ ਰਹੇ ਹੈ। ੧੯੭੬।","roman":"Baachat hee pateeyaa uthi aavhu joo byaah bikhai din teen rahe hai | 1976 |","meaning_en":"'Rise and come as soon as you read this letter; three days remain until the wedding.'","page":643,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":643,"meaning_status":"draft"},{"type":"verse","number":[1977],"number_text":"੧੯੭੭।","page":643,"lines":[{"gurmukhi":"ਤੀਨ ਬ੍ਯਾਹ ਮੈ ਦਿਨ ਰਹੇ ਇਉ ਕਹੀਐ ਦਿਜ ਗਾਥ।","roman":"Teen byaah mai din rahe iu kaheeai dij gaath |","meaning_en":"'Three days remain until the wedding': O Brahmin, tell the story thus;","page":643,"meaning_status":"draft"},{"gurmukhi":"ਤਜਿ ਬਿਲੰਬ ਆਵਹੁ ਪ੍ਰਭੂ ਪਤੀਆ ਪੜਿ ਦਿਜ ਸਾਥ। ੧੯੭੭।","roman":"Taji bilanb aavhu prabhoo pateeaa pari dij saath | 1977 |","meaning_en":"'Lord, leave delay and come with the Brahmin, having read the letter.'","page":643,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":643,"meaning_status":"draft"},{"type":"verse","number":[1978],"number_text":"੧੯੭੮।","page":643,"lines":[{"gurmukhi":"ਅਉ ਜਦੁਬੀਰ ਸੋ ਯੌ ਕਹੀਯੋ ਤੁਮਰੇ ਬਿਨੁ ਦੇਖਿ ਨਿਸਾ ਡਰੁ ਆਵੈ।","roman":"Au jadubeer so yau kaheeyo tumre binu dekhi nisaa daru aavai |","meaning_en":"'And say this to the Yadav hero: without you, seeing the night, fear comes over me.'","page":643,"meaning_status":"draft"},{"gurmukhi":"ਬਾਰ ਹੀ ਬਾਰ ਅਤਿ ਆਤੁਰ ਹ੍ਵੈ ਤਨ ਤਿਆਗਿ ਕਹਿਯੋ ਜੀਅ ਮੋਰ ਪਰਾਵੈ।","roman":"Baar hee baar ati aatur hvai tan tiaagi kahiyo jeea mor paraavai |","meaning_en":"'Again and again, in great distress, my soul wants to leave my body and flee,' she said.","page":643,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਾਚੀ ਪ੍ਰਤਛ ਭਯੋ ਸਸਿ ਪੂਰਨ ਸੋ ਹਮ ਕੋ ਅਤਿਸੈ ਕਰਿ ਤਾਵੈ।","roman":"Praachee pratachh bhayo sasi pooran so ham ko atisai kari taavai |","meaning_en":"'The full moon has risen in the east, and it torments me greatly.'","page":643,"meaning_status":"draft"},{"gurmukhi":"ਮੈਨ ਮਨੋ ਮੁਖ ਆਰੁਨ ਕੈ ਤੁਮਰੇ ਬਿਨੁ ਆਇ ਹਮੋ ਡਰ ਪਾਵੈ। ੧੯੭੮।","roman":"Main mano mukh aarun kai tumre binu aai hamo dar paavai | 1978 |","meaning_en":"'The god of love, as it were, with reddened face, comes and frightens me without you.'","page":643,"meaning_status":"draft","note":"ਮੈਨ: Kamdev, the god of love."}]},{"type":"verse","number":[1979],"number_text":"੧੯੭੯।","page":643,"lines":[{"gurmukhi":"ਲਾਗਿ ਰਹਿਓ ਤੁਹਿ ਓਰਹਿ ਸ੍ਯਾਮ ਜੂ ਮੈ ਇਹ ਬੇਰ ਘਨੀ ਹਟ ਕੇ।","roman":"Laagi rahio tuhi orhi syaam joo mai ih ber ghanee hat ke |","meaning_en":"'O Shyam ji, they stay fixed towards you, though I have pulled them back many times.'","page":643,"meaning_status":"draft","note":"The subject is the eyes (named in the last line)."},{"gurmukhi":"ਘਨਿ ਸ੍ਯਾਮ ਕੀ ਬੰਕ ਬਿਲੋਕਨ ਫਾਸ ਕੇ ਸੰਗਿ ਫਸੇ ਸੁ ਨਹੀ ਛੁਟਕੇ।","roman":"Ghani syaam kee bank bilokan phaas ke sangi phase su nahee chhutke |","meaning_en":"'Caught in the noose of the cloud-dark one's sidelong glances, they cannot get free.'","page":643,"meaning_status":"draft"},{"gurmukhi":"ਨਹੀ ਨੈਕੁ ਮੁਰਾਏ ਮੁਰੈ ਹਮਰੇ ਤੁਹਿ ਮੂਰਤਿ ਹੇਰਨ ਹੀ ਅਟਕੇ।","roman":"Nahee naiku muraae murai hamre tuhi moorti heran hee atke |","meaning_en":"'They do not turn back in the least when I turn them; they are caught on gazing at your form.'","page":643,"meaning_status":"draft"},{"gurmukhi":"ਕਬਿ ਸ੍ਯਾਮ ਭਨੇ ਸੰਗਿ ਲਾਜ ਕੇ ਆਜ ਭਏ ਦੋਊ ਨੈਨ ਬਟਾ ਨਟ ਕੇ। ੧੯੭੯।","roman":"Kabi syaam bhane sangi laaj ke aaj bhae do'oo nain bataa nat ke | 1979 |","meaning_en":"'Poet Shyam says, today, along with my modesty, both my eyes have become like a juggler's balls.'","page":643,"meaning_status":"draft","note":"ਬਟਾ ਨਟ ਕੇ: 'the balls of a juggler / acrobat', i.e. restless; uncertain."}]},{"type":"verse","number":[1980],"number_text":"੧੯੮੦।","page":643,"lines":[{"gurmukhi":"ਸਾਜ ਦਯੋ ਰਥ ਬਾਮਨ ਕੋ ਬਹੁਤੈ ਧਨੁ ਦੈ ਤਿਹ ਚਿਤ ਬਢਾਯੋ।","roman":"Saaj dayo rath baaman ko bahutai dhanu dai tih chit badhaayo |","meaning_en":"She had a chariot made ready for the Brahmin and, giving him much wealth, raised his spirits.","page":643,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰੀ ਬ੍ਰਿਜਨਾਥ ਲਿਆਵਨ ਕਾਜ ਪਠਿਯੋ ਚਿਤ ਮੈ ਤਿਨ ਹੂੰ ਸੁਖੁ ਪਾਯੋ।","roman":"Sree brijnaath liaavan kaaj pathiyo chit mai tin hoon sukhu paayo |","meaning_en":"She sent him to bring the Lord of Braj, and he too was glad at heart.","page":643,"meaning_status":"draft"},{"gurmukhi":"ਯੌ ਸੋਊ ਲੈ ਪਤੀਯਾ ਕੋ ਚਲਿਯੋ ਸੁ ਪ੍ਰਬੰਧ ਕਥਾ ਕਹਿ ਸ੍ਯਾਮ ਸੁਨਾਯੋ।","roman":"Yau so'oo lai pateeyaa ko chaliyo su prabandh kathaa kahi syaam sunaayo |","meaning_en":"Thus he set off with the letter; Shyam has told the course of the story.","page":643,"meaning_status":"draft"},{"gurmukhi":"ਮਾਨਹੁ ਪਉਨ ਕੇ ਗਉਨ ਹੂੰ ਤੇ ਸੁ ਸਿਤਾਬ ਦੈ ਸ੍ਰੀ ਜਦੁਬੀਰ ਪੈ ਆਯੋ। ੧੯੮੦।","roman":"Maanhu paun ke gaun hoon te su sitaab dai sree jadubeer pai aayo | 1980 |","meaning_en":"As if moving faster than the wind, he came swiftly to the Yadav hero.","page":643,"meaning_status":"draft","note":"ਸਿਤਾਬ: Persian 'quickly'."}]},{"type":"verse","number":[1981],"number_text":"੧੯੮੧।","page":644,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਬ੍ਰਿਜਨਾਥ ਕੋ ਬਾਸ ਜਹਾ ਸੁ ਕਹੈ ਕਬਿ ਸ੍ਯਾਮ ਪੁਰੀ ਅਤਿ ਨੀਕੀ।","roman":"Sree brijnaath ko baas jahaa su kahai kabi syaam puree ati neekee |","meaning_en":"The city where the Lord of Braj lived, says poet Shyam, was very fine.","page":644,"meaning_status":"draft"},{"gurmukhi":"ਬਜ੍ਰ ਖਚੇ ਅਰੁ ਲਾਲ ਜਵਾਹਿਰ ਜੋਤਿ ਜਗੈ ਅਤਿ ਹੀ ਸੁ ਮਨੀ ਕੀ।","roman":"Bajr khache aru laal javaahir joti jagai ati hee su manee kee |","meaning_en":"It was inlaid with diamonds, rubies and jewels, and the light of its gems shone brightly.","page":644,"meaning_status":"draft"},{"gurmukhi":"ਕਉਨ ਸਰਾਹ ਕਰੈ ਤਿਹ ਕੀ ਤੁਮ ਹੀ ਨ ਕਹੋ ਐਸੀ ਬੁਧਿ ਕਿਸੀ ਕੀ।","roman":"Kaun saraah karai tih kee tum hee na kaho aisee budhi kisee kee |","meaning_en":"Who can praise it? Tell me yourself, who has such understanding?","page":644,"meaning_status":"draft"},{"gurmukhi":"ਸੇਸ ਨਿਸੇਸ ਜਲੇਸ ਕੀ ਅਉਰ ਸੁਰੇਸ ਪੁਰੀ ਜਿਹ ਅਗ੍ਰਜ ਫੀਕੀ। ੧੯੮੧।","roman":"Ses nises jales kee aur sures puree jih agraj pheekee | 1981 |","meaning_en":"Beside it the cities of Shesh, of the moon, of Varun and of Indra looked pale.","page":644,"meaning_status":"draft","note":"ਨਿਸੇਸ: lord of night, the moon; ਜਲੇਸ: lord of waters, Varun; ਸੁਰੇਸ: lord of gods, Indra."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":644,"meaning_status":"draft"},{"type":"verse","number":[1982],"number_text":"੧੯੮੨।","page":644,"lines":[{"gurmukhi":"ਐਸੀ ਪੁਰੀ ਨਿਹਾਰ ਕੈ ਅਤਿ ਚਿਤਿ ਹਰਖ ਬਢਾਇ।","roman":"Aisee puree nihaar kai ati chiti harakh badhaai |","meaning_en":"Seeing such a city, with great joy growing in his heart,","page":644,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰੀ ਬ੍ਰਿਜਪਤਿ ਕੋ ਗ੍ਰਿਹ ਜਹਾ ਤਹਿ ਦਿਜ ਪਹੁਚਿਓ ਜਾਇ। ੧੯੮੨।","roman":"Sree brijapti ko grih jahaa tahi dij pahuchio jaai | 1982 |","meaning_en":"the Brahmin went and arrived where the house of the Lord of Braj was.","page":644,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":644,"meaning_status":"draft"},{"type":"verse","number":[1983],"number_text":"੧੯੮੩।","page":644,"lines":[{"gurmukhi":"ਦੇਖਤ ਹੀ ਬ੍ਰਿਜਨਾਥ ਦਿਜੋਤਮ ਠਾਢ ਭਯੋ ਉਠਿ ਆਗੇ ਬੁਲਾਯੋ।","roman":"Dekhat hee brijnaath dijotam thaadh bhayo uthi aage bulaayo |","meaning_en":"As soon as the Lord of Braj saw the excellent Brahmin, he rose to his feet and called him forward.","page":644,"meaning_status":"draft"},{"gurmukhi":"ਲੈ ਦਿਜੈ ਆਗੈ ਧਰੀ ਪਤੀਆ ਤਿਹ ਬਾਚਤ ਹੀ ਪ੍ਰਭ ਜੀ ਸੁਖ ਪਾਯੋ।","roman":"Lai dijai aagai dharee pateeaa tih baachat hee prabh jee sukh paayo |","meaning_en":"The Brahmin took out the letter and laid it before him; reading it, the Lord was delighted.","page":644,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਯੰਦਨ ਸਾਜਿ ਚੜਿਓ ਅਪੁਨੇ ਸੋਊ ਸੰਗਿ ਲਯੋ ਮਨੋ ਪਉਨ ਹ੍ਵੈ ਧਾਯੋ।","roman":"Syandan saaji chario apune so'oo sangi layo mano paun hvai dhaayo |","meaning_en":"He had his chariot made ready, mounted it, took the Brahmin along, and sped off as if he had become the wind,","page":644,"meaning_status":"draft"},{"gurmukhi":"ਮਾਨੋ ਛੁਧਾਤਰੁ ਹੋਇ ਅਤਿ ਹੀ ਮ੍ਰਿਗ ਝੁੰਡ ਤਕੈ ਉਠਿ ਕੇਹਰਿ ਆਯੋ। ੧੯੮੩।","roman":"Maano chhudhaatru hoi ati hee mrig jhund takai uthi kehri aayo | 1983 |","meaning_en":"as though a very hungry lion had spotted a herd of deer and sprung up.","page":644,"meaning_status":"draft"}]},{"type":"verse","number":[1984],"number_text":"੧੯੮੪।","page":644,"lines":[{"gurmukhi":"ਇਤ ਸ੍ਯਾਮ ਜੂ ਸ੍ਯੰਦਨ ਸਾਜਿ ਚੜਿਯੋ ਉਤ ਲੈ ਸਿਸੁਪਾਲ ਘਨੋ ਦਲੁ ਆਯੋ।","roman":"It syaam joo syandan saaji chariyo ut lai sisupaal ghano dalu aayo |","meaning_en":"Here Shyam ji mounted his prepared chariot; there Shishupal came with a great army.","page":644,"meaning_status":"draft"},{"gurmukhi":"ਆਵਤ ਸੋ ਇਨ ਹੂੰ ਸੁਨਿ ਕੈ ਪੁਰ ਦ੍ਵਾਰ ਬਜਾਰ ਜੁ ਥੇ ਸੁ ਬਨਾਯੋ।","roman":"Aavat so in hoon suni kai pur dvaar bajaar ju the su banaayo |","meaning_en":"Hearing of his coming, these people decorated the city gates and the markets.","page":644,"meaning_status":"draft"},{"gurmukhi":"ਸੈਨ ਬਨਾਇ ਭਲੀ ਇਤ ਤੇ ਰੁਕਮਾਦਿਕ ਆਗੇ ਤੇ ਲੈਨ ਕਉ ਧਾਯੋ।","roman":"Sain banaai bhalee it te rukmaadik aage te lain kau dhaayo |","meaning_en":"Arraying a fine army, Rukmi and the others went out from here to receive him.","page":644,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਯਾਮ ਭਨੈ ਸਭ ਹੀ ਭਟਵਾ ਅਪਨੇ ਮਨ ਮੈ ਅਤਿ ਹੀ ਸੁਖੁ ਪਾਯੋ। ੧੯੮੪।","roman":"Syaam bhanai sabh hee bhatvaa apne man mai ati hee sukhu paayo | 1984 |","meaning_en":"Shyam says, all the warriors felt great joy in their minds.","page":644,"meaning_status":"draft"}]},{"type":"verse","number":[1985],"number_text":"੧੯੮੫।","page":644,"lines":[{"gurmukhi":"ਅਉਰ ਬਡੇ ਨ੍ਰਿਪ ਆਵਤ ਭੇ ਚੁਤਰੰਗ ਚਮੂੰ ਸੁ ਘਨੀ ਸੰਗਿ ਲੈ ਕੇ।","roman":"Aur bade nrip aavat bhe chutrang chamoon su ghanee sangi lai ke |","meaning_en":"Other great kings also came, bringing large fourfold armies with them,","page":644,"meaning_status":"draft"},{"gurmukhi":"ਹੇਰਨ ਬ੍ਯਾਹ ਰੁਕੰਮਿਨੀ ਕੋ ਅਤਿ ਹੀ ਚਿਤ ਮੈ ਸੁ ਹੁਲਾਸ ਬਢੈ ਕੈ।","roman":"Heran byaah rukanminee ko ati hee chit mai su hulaas badhai kai |","meaning_en":"to see Rukmini's wedding, with great delight swelling in their hearts,","page":644,"meaning_status":"draft"},{"gurmukhi":"ਭੇਰਿ ਘਨੀ ਸਹਨਾਇ ਸਿੰਗੇ ਰਨ ਦੁੰਦਭਿ ਅਉ ਤੁਰਹੀਨ ਬਜੈ ਕੈ।","roman":"Bheri ghanee sahnaai singe ran dundbhi au turheen bajai kai |","meaning_en":"sounding many kettle-drums, shehnais, horns, war-drums and trumpets.","page":644,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਯਾਮ ਇਤੇ ਛਪਿ ਆਵਤ ਭਯੋ ਕਬਿ ਸ੍ਯਾਮ ਭਨੈ ਤਿਨ ਕਾਰਨ ਛੈ ਕੈ। ੧੯੮੫।","roman":"Syaam ite chhapi aavat bhayo kabi syaam bhanai tin kaaran chhai kai | 1985 |","meaning_en":"Here Shyam came in secret, says poet Shyam, keeping himself hidden for their sake.","page":644,"meaning_status":"draft","note":"ਤਿਨ ਕਾਰਨ ਛੈ ਕੈ: read as 'hiding because of them'; uncertain."}]},{"type":"verse","number":[1986],"number_text":"੧੯੮੬।","page":644,"lines":[{"gurmukhi":"ਸ੍ਯਾਮ ਭਨੈ ਜੋਊ ਬੇਦ ਕੇ ਬੀਚ ਲਿਖੀ ਬਿਧਿ ਬ੍ਯਾਹ ਕੀ ਸੋ ਦੁਹੂੰ ਕੀਨੀ।","roman":"Syaam bhanai jo'oo bed ke beech likhee bidhi byaah kee so duhoon keenee |","meaning_en":"Shyam says, whatever rite of marriage is written in the Vedas, both sides performed it.","page":644,"meaning_status":"draft"},{"gurmukhi":"ਮੰਤ੍ਰਨ ਸੋ ਅਭਿਮੰਤ੍ਰਨ ਕੈ ਭੂਅ ਫੇਰਨ ਕੀ ਸੁ ਪਵਿਤ੍ਰ ਕੈ ਲੀਨੀ।","roman":"Mantran so abhimantran kai bhooa pheran kee su pavitr kai leenee |","meaning_en":"Consecrating it with mantras, they purified the ground for the marriage rounds.","page":644,"meaning_status":"draft"},{"gurmukhi":"ਅਉਰ ਜਿਤੇ ਦਿਜ ਸ੍ਰੇਸਟ ਹੁਤੇ ਤਿਨ ਕੋ ਅਤਿ ਹੀ ਦਛਨਾ ਤਿਨ ਦੀਨੀ।","roman":"Aur jite dij sresat hute tin ko ati hee dachhnaa tin deenee |","meaning_en":"And all the excellent Brahmins there were given very large offerings.","page":644,"meaning_status":"draft"},{"gurmukhi":"ਬੇਦੀ ਰਚੀ ਭਲੀ ਭਾਤਹ ਸੋ ਜਦੁਬੀਰ ਬਿਨਾ ਸਭ ਲਾਗਤ ਹੀਨੀ। ੧੯੮੬।","roman":"Bedee rachee bhalee bhaatah so jadubeer binaa sabh laagat heenee | 1986 |","meaning_en":"The altar was finely made, but without the Yadav hero it all looked bare.","page":644,"meaning_status":"draft"}]},{"type":"verse","number":[1987],"number_text":"੧੯੮੭।","page":644,"lines":[{"gurmukhi":"ਤਉ ਹੀ ਲਉ ਲੈ ਕਿਹ ਸੰਗਿ ਪੁਰੋਹਿਤ ਦੇਵੀ ਕੀ ਪੂਜਾ ਕੇ ਕਾਜ ਸਿਧਾਰੇ।","roman":"Tau hee lau lai kih sangi purohit devee kee poojaa ke kaaj sidhaare |","meaning_en":"Just then they took her, with the family priest, and set out to worship the goddess.","page":644,"meaning_status":"draft","note":"ਕਿਹ printed; read as ਤਿਹ 'her'; uncertain."},{"gurmukhi":"ਸ੍ਯੰਦਨ ਪੈ ਚੜਵਾਇ ਤਬੈ ਤਿਹ ਪਾਛੇ ਚਲੇ ਤਿਹ ਕੇ ਭਟ ਭਾਰੇ।","roman":"Syandan pai charvaai tabai tih paachhe chale tih ke bhat bhaare |","meaning_en":"Seating her on a chariot, her mighty warriors then went behind her.","page":644,"meaning_status":"draft"},{"gurmukhi":"ਯਾ ਬਿਧਿ ਦੇਖਿ ਪ੍ਰਤਾਪ ਘਨੋ ਮੁਖ ਤੇ ਰੁਕਮੈ ਇਹ ਬੈਨ ਉਚਾਰੇ।","roman":"Yaa bidhi dekhi prataap ghano mukh te rukmai ih bain uchaare |","meaning_en":"Seeing such great splendour, Rukmi uttered these words:","page":644,"meaning_status":"draft"},{"gurmukhi":"ਰਾਖੀ ਪ੍ਰਭੂ ਪਤਿ ਮੋਰ ਭਲੀ ਬਿਧਿ ਧੰਨ੍ਯ ਕਹਿਯੋ ਅਬ ਭਾਗ ਹਮਾਰੇ। ੧੯੮੭।","roman":"Raakhee prabhoo pati mor bhalee bidhi dhanny kahiyo ab bhaag hamaare | 1987 |","meaning_en":"'The Lord has kept my honour well; blessed now is our fortune,' he said.","page":644,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":645,"meaning_status":"draft"},{"type":"verse","number":[1988],"number_text":"੧੯੮੮।","page":645,"lines":[{"gurmukhi":"ਜਬ ਰੁਕਮਿਨੀ ਤਿਹ ਮੰਦਿਰ ਗਈ। ਦੁਖ ਸੰਗਿ ਬਿਹਬਲ ਅਤਿ ਹੀ ਭਈ।","roman":"Jab rukminee tih mandir gaee | dukh sangi bihbal ati hee bhaee |","meaning_en":"When Rukmini went to that temple, she was utterly distraught with grief.","page":645,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨਿ ਇਵ ਰੋਇ ਸਿਵਾ ਸੰਗਿ ਰਰਿਓ। ਤੁਹਿ ਤੇ ਮੋਹਿ ਇਹੀ ਬਰੁ ਸਰਿਓ। ੧੯੮੮।","roman":"Tini iv roi sivaa sangi rario | tuhi te mohi ihee baru sario | 1988 |","meaning_en":"Weeping, she spoke thus to Shiva (the goddess): 'From you this is the boon I have got.'","page":645,"meaning_status":"draft","note":"ਸਿਵਾ: the goddess, consort of Shiva. ਬਰੁ: 'boon' or 'husband'; spoken bitterly."}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":645,"meaning_status":"draft"},{"type":"verse","number":[1989],"number_text":"੧੯੮੯।","page":645,"lines":[{"gurmukhi":"ਦੂਰਿ ਦਈ ਸਖੀਆ ਕਰਿ ਕੈ ਕਰਿ ਲੀਨ ਛੁਰੀ ਕਹਿਓ ਘਾਤ ਕਰੈ ਹਉ।","roman":"Doori daee sakheeaa kari kai kari leen chhuree kahio ghaat karai hau |","meaning_en":"Sending her companions away, she took a dagger in her hand and said, 'I will kill myself.'","page":645,"meaning_status":"draft"},{"gurmukhi":"ਮੈ ਬਹੁ ਸੇਵ ਸਿਵਾ ਕੀ ਕਰੀ ਤਿਹ ਤੇ ਸਭ ਹੌ ਸੁ ਇਹੈ ਫਲੁ ਪੈ ਹਉ।","roman":"Mai bahu sev sivaa kee karee tih te sabh hau su ihai phalu pai hau |","meaning_en":"'I served the goddess a great deal, and from her this is all the fruit I get.'","page":645,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਾਨਨ ਧਾਮਿ ਪਠੋ ਜਮ ਕੇ ਇਹ ਦੇਹੁਰੇ ਊਪਰ ਪਾਪ ਚੜੈ ਹਉ।","roman":"Praanan dhaami patho jam ke ih dehure oopar paap charai hau |","meaning_en":"'I will send my life to Yama's abode and lay the sin upon this shrine,'","page":645,"meaning_status":"draft"},{"gurmukhi":"ਕੈ ਇਹ ਕੋ ਰਿਝਵਾਇ ਅਬੈ ਬਰਿਬੋ ਹਰਿ ਕੋ ਇਹ ਤੇ ਬਰੁ ਪੈ ਹਉ। ੧੯੮੯।","roman":"Kai ih ko rijhvaai abai baribo hari ko ih te baru pai hau | 1989 |","meaning_en":"'or else, pleasing her now, I will gain from her the boon of marrying Hari.'","page":645,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਦੇਵੀ ਜੂ ਬਾਚ ਰੁਕਮਿਨੀ ਸੋ","gurmukhi":"ਦੇਵੀ ਜੂ ਬਾਚ ਰੁਕਮਿਨੀ ਸੋ","roman":"Devee joo baach rukminee so","meaning_en":"The goddess said to Rukmini:","page":645,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":645,"meaning_status":"draft"},{"type":"verse","number":[1990],"number_text":"੧੯੯੦।","page":645,"lines":[{"gurmukhi":"ਦੇਖਿ ਦਸਾ ਤਿਹ ਕੀ ਜਗਮਾਤ ਪ੍ਰਤਛ ਹ੍ਵੈ ਤਾਹਿ ਕਹਿਓ ਹਸਿ ਐਸੇ।","roman":"Dekhi dasaa tih kee jagmaat pratachh hvai taahi kahio hasi aise |","meaning_en":"Seeing her plight, the Mother of the world appeared before her and, laughing, said thus:","page":645,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਯਾਮ ਕੀ ਬਾਮ ਤੈ ਆਪਨੇ ਚਿਤ ਕਰੋ ਦੁਚਿਤਾ ਫੁਨਿ ਰੰਚ ਨ ਕੈਸੇ।","roman":"Syaam kee baam tai aapne chit karo duchitaa phuni ranch na kaise |","meaning_en":"'You are Shyam's wife; do not be in two minds about it in the least.'","page":645,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਸਿਸੁਪਾਲ ਕੇ ਹੈ ਚਿਤ ਮੈ ਨਹਿ ਹ੍ਵੈ ਹੈ ਸੋਊ ਤਿਹ ਕੀ ਸੁ ਰੁਚੈ ਸੇ।","roman":"Jo sisupaal ke hai chit mai nahi hvai hai so'oo tih kee su ruchai se |","meaning_en":"'What is in Shishupal's mind will not come about as he wishes.'","page":645,"meaning_status":"draft"},{"gurmukhi":"ਹੁਇ ਹੈ ਅਵਸਿ ਸੋਊ ਸੁਨਿ ਰੀ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਤੁਮਰੇ ਜੀ ਜੈਸੇ। ੧੯੯੦।","roman":"Hui hai avsi so'oo suni ree kabi syaam kahai tumre jee jaise | 1990 |","meaning_en":"'Listen, girl: it will surely be, says poet Shyam, just as your heart wishes.'","page":645,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":645,"meaning_status":"draft"},{"type":"verse","number":[1991],"number_text":"੧੯੯੧।","page":645,"lines":[{"gurmukhi":"ਯੌ ਬਰੁ ਲੈ ਕੇ ਸਿਵਾ ਤੇ ਪ੍ਰਸੰਨ ਚਲੀ ਹੁਇ ਚਿਤ।","roman":"Yau baru lai ke sivaa te prasann chalee hui chit |","meaning_en":"Taking this boon from the goddess, she went away, glad at heart;","page":645,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਯੰਦਨ ਪੈ ਚੜਿ ਮਨ ਬਿਖੈ ਚਹਿ ਸ੍ਰੀ ਜਦੁਪਤਿ ਮਿਤ। ੧੯੯੧।","roman":"Syandan pai chari man bikhai chahi sree jadupti mit | 1991 |","meaning_en":"she mounted the chariot, longing in her mind for her beloved, the Lord of the Yadavs.","page":645,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":645,"meaning_status":"draft"},{"type":"verse","number":[1992],"number_text":"੧੯੯੨।","page":645,"lines":[{"gurmukhi":"ਚੜੀ ਜਾਤ ਹੁਤੀ ਸੋਊ ਸ੍ਯੰਦਨ ਪੈ ਬ੍ਰਿਜ ਨਾਇਕ ਦ੍ਰਿਸਟਿ ਬਿਖੈ ਕਰਿ ਕੈ।","roman":"Charee jaat hutee so'oo syandan pai brij naaik dristi bikhai kari kai |","meaning_en":"As she was going along on the chariot, the Lord of Braj caught sight of her;","page":645,"meaning_status":"draft","note":"ਬ੍ਰਿਜ ਨਾਇਕ ਦ੍ਰਿਸਟਿ ਬਿਖੈ ਕਰਿ ਕੈ: may also mean she kept the Lord of Braj in her sight (mind); uncertain."},{"gurmukhi":"ਅਰੁ ਸਤ੍ਰਨ ਸੈਨ ਨਿਹਾਰਿ ਘਨੀ ਤਿਹ ਤੇ ਨਹੀ ਸ੍ਯਾਮ ਭਨੈ ਡਰਿ ਕੈ।","roman":"Aru satran sain nihaari ghanee tih te nahee syaam bhanai dari kai |","meaning_en":"and seeing the great army of the enemies, he was not afraid of it, says Shyam.","page":645,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਭ ਆਇ ਪਰਿਓ ਤਿਹ ਮਧਿ ਬਿਖੈ ਇਹ ਲੇਤ ਹੋ ਰੇ ਇਮ ਉਚਰਿ ਕੈ।","roman":"Prabh aai pario tih madhi bikhai ih let ho re im uchri kai |","meaning_en":"The Lord came and fell into their midst, crying out, 'Hey, I am taking her!'","page":645,"meaning_status":"draft"},{"gurmukhi":"ਬਲੁ ਧਾਰਿ ਲਈ ਰਥ ਭੀਤਰ ਡਾਰਿ ਮੁਰਾਰਿ ਤਬੈ ਬਹੀਯਾ ਧਰਿ ਕੈ। ੧੯੯੨।","roman":"Balu dhaari laee rath bheetar daari muraari tabai baheeyaa dhari kai | 1992 |","meaning_en":"Using his strength, Murari then seized her by the arm and put her into the chariot.","page":645,"meaning_status":"draft"}]},{"type":"verse","number":[1993],"number_text":"੧੯੯੩।","page":645,"lines":[{"gurmukhi":"ਡਾਰਿ ਰੁਕਮਿਨੀ ਸ੍ਯੰਦਨ ਪੈ ਸਭ ਸੂਰਨ ਸੋ ਇਹ ਭਾਤਿ ਸੁਨਾਈ।","roman":"Daari rukminee syandan pai sabh sooran so ih bhaati sunaaee |","meaning_en":"Having put Rukmini on the chariot, he declared thus to all the warriors:","page":645,"meaning_status":"draft"},{"gurmukhi":"ਜਾਤ ਹੋ ਰੇ ਇਹ ਕੋ ਅਬ ਲੈ ਇਹ ਕੈ ਰੁਕਮੈ ਅਬ ਦੇਖਤ ਭਾਈ।","roman":"Jaat ho re ih ko ab lai ih kai rukmai ab dekhat bhaaee |","meaning_en":"'Hey, I am going now, taking her away, while her brother Rukmi looks on.'","page":645,"meaning_status":"draft"},{"gurmukhi":"ਪਉਰਖ ਹੈ ਜਿਹ ਸੂਰ ਬਿਖੈ ਸੋਊ ਯਾਹਿ ਛਡਾਇਨ ਮਾਡਿ ਲਰਾਈ।","roman":"Paurakh hai jih soor bikhai so'oo yaahi chhadaain maadi laraaee |","meaning_en":"'Whichever warrior has any manliness, let him do battle to free her.'","page":645,"meaning_status":"draft"},{"gurmukhi":"ਆਜ ਸਭੋ ਮਰਿ ਹੋ ਟਰਿ ਨਹੀ ਸ੍ਯਾਮ ਭਨੈ ਮੁਹਿ ਰਾਮ ਦੁਹਾਈ। ੧੯੯੩।","roman":"Aaj sabho mari ho tari nahee syaam bhanai muhi raam duhaaee | 1993 |","meaning_en":"'Today you shall all die; I will not turn back,' says Shyam; 'I swear it by Ram.'","page":645,"meaning_status":"draft","note":"ਮੁਹਿ ਰਾਮ ਦੁਹਾਈ: an oath, 'by Ram' (possibly Balram); uncertain."}]},{"type":"verse","number":[1994],"number_text":"੧੯੯੪।","page":645,"lines":[{"gurmukhi":"ਯੌ ਬਤੀਯਾ ਸੁਨਿ ਕੈ ਤਿਹ ਕੀ ਸਭ ਆਇ ਪਰੇ ਅਤਿ ਕ੍ਰੋਧ ਬਢੈ ਕੈ।","roman":"Yau bateeyaa suni kai tih kee sabh aai pare ati krodh badhai kai |","meaning_en":"Hearing his words, they all fell upon him in rising fury.","page":645,"meaning_status":"draft"},{"gurmukhi":"ਰੋਸ ਭਰੇ ਭਟ ਠੋਕਿ ਭੁਜਾ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਅਤਿ ਕ੍ਰੋਧਤ ਹ੍ਵੈ ਕੈ।","roman":"Ros bhare bhat thoki bhujaa kabi syaam kahai ati krodhat hvai kai |","meaning_en":"The warriors, full of wrath, slapped their arms, says poet Shyam, being very angry,","page":645,"meaning_status":"draft"},{"gurmukhi":"ਭੇਰਿ ਘਨੀ ਸਹਨਾਇ ਸਿੰਗੇ ਰਨ ਦੁੰਦਭਿ ਅਉ ਅਤਿ ਤਾਲ ਬਜੈ ਕੈ।","roman":"Bheri ghanee sahnaai singe ran dundbhi au ati taal bajai kai |","meaning_en":"sounding many kettle-drums, shehnais, horns, war-drums and loud cymbals.","page":646,"meaning_status":"draft"},{"gurmukhi":"ਸੋ ਜਦੁਬੀਰ ਸਰਾਸਨ ਲੈ ਛਿਨ ਬੀਚ ਦਏ ਜਮਲੋਕਿ ਪਠੈ ਕੈ। ੧੯੯੪।","roman":"So jadubeer saraasan lai chhin beech dae jamloki pathai kai | 1994 |","meaning_en":"The Yadav hero took up his bow and in an instant sent them to Yama's world.","page":646,"meaning_status":"draft"}]},{"type":"verse","number":[1995],"number_text":"੧੯੯੫।","page":646,"lines":[{"gurmukhi":"ਜੋ ਭਟ ਕਾਹੂੰ ਤੇ ਨੈਕੁ ਡਰੇ ਨਹਿ ਸੋ ਰਿਸ ਕੈ ਤਿਹ ਸਾਮੁਹੇ ਆਏ।","roman":"Jo bhat kaahoon te naiku dare nahi so ris kai tih saamuhe aae |","meaning_en":"Warriors who did not fear anyone in the least came angrily before him,","page":646,"meaning_status":"draft"},{"gurmukhi":"ਗਾਲ ਬਜਾਇ ਬਜਾਇ ਕੈ ਦੁੰਦਭਿ ਜਿਉ ਘਨ ਸਾਵਨ ਕੇ ਘਹਰਾਏ।","roman":"Gaal bajaai bajaai kai dundbhi jiu ghan saavan ke ghahraae |","meaning_en":"boasting loudly and thundering like war-drums, like the rumbling clouds of Sawan.","page":646,"meaning_status":"draft","note":"ਗਾਲ ਬਜਾਇ: read as 'boasting loudly'; uncertain."},{"gurmukhi":"ਸ੍ਰੀ ਜਦੁਬੀਰ ਕੇ ਬਾਨ ਛੁਟੇ ਨ ਟਿਕੇ ਪਲ ਏਕ ਤਹਾ ਠਹਰਾਏ।","roman":"Sree jadubeer ke baan chhute na tike pal ek tahaa thahraae |","meaning_en":"When the Yadav hero's arrows flew, they could not stand there even for a moment.","page":646,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਪਰੇ ਹੀ ਕਰਾਹਤ ਬੀਰ ਬਲੀ ਇਕ ਅੰਤ ਕੇ ਧਾਮਿ ਸਿਧਾਏ। ੧੯੯੫।","roman":"Ek pare hee karaahat beer balee ik ant ke dhaami sidhaae | 1995 |","meaning_en":"Some mighty heroes lay groaning; some departed to the abode of death.","page":646,"meaning_status":"draft"}]},{"type":"verse","number":[1996],"number_text":"੧੯੯੬।","page":646,"lines":[{"gurmukhi":"ਐਸੀ ਨਿਹਾਰਿ ਦਸਾ ਦਲ ਕੀ ਸਿਸੁ ਪਾਲ ਤਬੈ ਰਿਸ ਆਪਹਿ ਆਯੋ।","roman":"Aisee nihaari dasaa dal kee sisu paal tabai ris aaphi aayo |","meaning_en":"Seeing his army in such a state, Shishupal himself then came on in anger.","page":646,"meaning_status":"draft"},{"gurmukhi":"ਆਇ ਕੈ ਸ੍ਯਾਮ ਸੋ ਐਸੋ ਕਹਿਓ ਨ ਜਰਾਸੰਧਿ ਹਉ ਜੋਊ ਤੋਹਿ ਭਗਾਯੋ।","roman":"Aai kai syaam so aiso kahio na jaraasandhi hau jo'oo tohi bhagaayo |","meaning_en":"Coming up, he said to Shyam: 'I am not Jarasandh, who made you run away.'","page":646,"meaning_status":"draft","note":"Translated as printed; the point of the taunt is not fully clear."},{"gurmukhi":"ਯੌ ਬਤੀਯਾ ਕਹਿ ਕੈ ਕਸ ਕੈ ਧਨੁ ਕਾਨ ਪ੍ਰਮਾਨ ਲਉ ਬਾਨ ਚਲਾਯੋ।","roman":"Yau bateeyaa kahi kai kas kai dhanu kaan pramaan lau baan chalaayo |","meaning_en":"Saying these words, he drew his bow to his ear and shot an arrow,","page":646,"meaning_status":"draft"},{"gurmukhi":"ਮਾਨਹੁ ਕ੍ਰੋਧ ਸਭੈ ਤਿਹ ਕੋ ਸੁ ਪ੍ਰਤਛ ਹੈ ਸ੍ਯਾਮ ਕੇ ਊਪਰ ਧਾਯੋ। ੧੯੯੬।","roman":"Maanhu krodh sabhai tih ko su pratachh hai syaam ke oopar dhaayo | 1996 |","meaning_en":"as though all his anger had taken visible form and rushed upon Shyam.","page":646,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":646,"meaning_status":"draft"},{"type":"verse","number":[1997],"number_text":"੧੯੯੭।","page":646,"lines":[{"gurmukhi":"ਸੋ ਸਰ ਆਵਤ ਦੇਖ ਕੈ ਕ੍ਰੁਧਤ ਹੁਇ ਬ੍ਰਿਜ ਨਾਥ।","roman":"So sar aavat dekh kai krudhat hui brij naath |","meaning_en":"Seeing that arrow coming, the Lord of Braj grew angry,","page":646,"meaning_status":"draft"},{"gurmukhi":"ਕਟਿ ਮਾਰਗ ਭੀਤਰ ਦਯੋ ਏਕ ਬਾਨ ਕੇ ਸਾਥ। ੧੯੯੭।","roman":"Kati maarag bheetar dayo ek baan ke saath | 1997 |","meaning_en":"and cut it down on its way with a single arrow.","page":646,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":646,"meaning_status":"draft"},{"type":"verse","number":[1998],"number_text":"੧੯੯੮।","page":646,"lines":[{"gurmukhi":"ਸਰ ਕਾਟਿ ਕੈ ਸ੍ਯੰਦਨ ਕਾਟਿ ਦਯੋ ਅਰੁ ਸੂਤ ਕੋ ਸੀਸ ਦਯੋ ਕਟਿ ਕੈ।","roman":"Sar kaati kai syandan kaati dayo aru soot ko sees dayo kati kai |","meaning_en":"Having cut the arrow, he cut down the chariot and cut off the charioteer's head;","page":646,"meaning_status":"draft"},{"gurmukhi":"ਅਰੁ ਚਾਰੋ ਹੀ ਅਸ੍ਵਨ ਸੀਸ ਕਟੇ ਬਹੁ ਢਾਲਨ ਕੇ ਤਬ ਹੀ ਝਟਿ ਕੈ।","roman":"Aru chaaro hee asvan sees kate bahu dhaalan ke tab hee jhati kai |","meaning_en":"and at once he cut off the heads of all four horses, through many shields.","page":646,"meaning_status":"draft","note":"ਬਹੁ ਢਾਲਨ ਕੇ ... ਝਟਿ ਕੈ: sense not fully clear; uncertain."},{"gurmukhi":"ਫਿਰਿ ਦਉਰਿ ਚਪੇਟ ਚਟਾਕ ਹਨਿਓ ਗਿਰ ਗਯੋ ਜਬ ਚੋਟ ਲਗੀ ਭਟਿ ਕੈ।","roman":"Phiri dauri chapet chataak hanio gir gayo jab chot lagee bhati kai |","meaning_en":"Then, running up, he struck him a resounding slap; when the blow landed, the warrior fell.","page":646,"meaning_status":"draft"},{"gurmukhi":"ਤੁਮ ਹੀ ਨ ਕਹੋ ਭਟ ਕਉਨ ਬੀਯੋ ਜਗ ਮੈ ਜੋਊ ਸ੍ਯਾਮ ਜੂ ਸੋ ਅਟਕੈ। ੧੯੯੮।","roman":"Tum hee na kaho bhat kaun beeyo jag mai jo'oo syaam joo so atkai | 1998 |","meaning_en":"Tell me yourself: what other warrior is there in the world who could stand up to Shyam ji?","page":646,"meaning_status":"draft"}]},{"type":"verse","number":[1999],"number_text":"੧੯੯੯।","page":646,"lines":[{"gurmukhi":"ਚਿਤ ਮੈ ਜਿਨ ਧਿਆਨ ਧਰਿਯੋ ਹਿਤ ਕੈ ਸੋਊ ਸ੍ਰੀ ਪਤਿ ਲੋਕਹਿ ਕੋ ਸਟਿਕਿਯੋ।","roman":"Chit mai jin dhiaan dhariyo hit kai so'oo sree pati lokhi ko satikiyo |","meaning_en":"Whoever has lovingly fixed his mind on him in meditation has passed on to the world of the Lord of Lakshmi.","page":646,"meaning_status":"draft","note":"ਸ੍ਰੀ ਪਤਿ ਲੋਕਹਿ ਕੋ ਸਟਿਕਿਯੋ: read as 'slipped away to Vishnu's world'; uncertain."},{"gurmukhi":"ਪਗ ਰੋਪ ਜੋਊ ਅਟਕਿਯੋ ਪ੍ਰਭੂ ਸੋ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਪਲ ਸੋ ਨ ਟਿਕਿਯੋ।","roman":"Pag rop jo'oo atkiyo prabhoo so kabi syaam kahai pal so na tikiyo |","meaning_en":"Whoever planted his feet and stood against the Lord, says poet Shyam, did not last a moment.","page":646,"meaning_status":"draft"},{"gurmukhi":"ਅਟਕਿਯੋ ਜੋਊ ਪ੍ਰੇਮ ਸੋ ਬੇਧ ਕੈ ਲੋਕ ਚਲਿਯੋ ਤਿਹ ਕਉ ਨ ਕਿਨ ਹੀ ਹਟਕਿਯੋ।","roman":"Atkiyo jo'oo prem so bedh kai lok chaliyo tih kau na kin hee hatkiyo |","meaning_en":"Whoever was held fast, pierced by love, went on to that world, and no one stopped him.","page":646,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਨੈਕੁ ਬਿਰੋਧ ਹੀਯੋ ਸਟਕਿਯੋ ਨਰ ਸੋ ਸਭ ਹੀ ਭੂਅ ਮੋ ਪਟਕਿਯੋ। ੧੯੯੯।","roman":"Jih naiku birodh heeyo satkiyo nar so sabh hee bhooa mo patkiyo | 1999 |","meaning_en":"Whoever's heart turned even slightly to hostility, every such man he dashed to the ground.","page":646,"meaning_status":"draft"}]},{"type":"verse","number":[2000],"number_text":"੨੦੦੦।","page":646,"lines":[{"gurmukhi":"ਫਉਜ ਬਿਦਾਰ ਘਨੀ ਬ੍ਰਿਜਨਾਥ ਬਿਮੁੰਛਤ ਕੈ ਸਿਸੁਪਾਲ ਗਿਰਾਯੋ।","roman":"Phauj bidaar ghanee brijnaath bimunchhat kai sisupaal giraayo |","meaning_en":"Destroying a great army, the Lord of Braj knocked Shishupal down unconscious.","page":646,"meaning_status":"draft"},{"gurmukhi":"ਅਉਰ ਜਿਤੋ ਦਲੁ ਠਾਢੋ ਹੁਤੋ ਸੋਊ ਦੇਖਿ ਦਸਾ ਕਰਿ ਤ੍ਰਾਸ ਪਰਾਯੋ।","roman":"Aur jito dalu thaadho huto so'oo dekhi dasaa kari traas paraayo |","meaning_en":"And all the army that was standing there, seeing this, fled in terror.","page":646,"meaning_status":"draft"},{"gurmukhi":"ਫੇਰਿ ਰਹੇ ਤਿਨ ਕੋ ਬਹੁ ਬਾਰਿ ਕੋਊ ਫਿਰਿ ਜੁਧ ਕੇ ਕਾਜ ਨ ਆਯੋ।","roman":"Pheri rahe tin ko bahu baari ko'oo phiri judh ke kaaj na aayo |","meaning_en":"They were turned back many times, but none came again to fight.","page":646,"meaning_status":"draft"},{"gurmukhi":"ਤਉ ਰੁਕਮੀ ਦਲ ਲੈ ਬਹੁਤੋ ਸੰਗਿ ਆਪਨੇ ਆਪ ਹੀ ਜੁਧ ਕੋ ਧਾਯੋ। ੨੦੦੦।","roman":"Tau rukmee dal lai bahuto sangi aapne aap hee judh ko dhaayo | 2000 |","meaning_en":"Then Rukmi, taking a large army with him, himself rushed into battle.","page":646,"meaning_status":"draft"}]},{"type":"verse","number":[2001],"number_text":"੨੦੦੧।","page":647,"lines":[{"gurmukhi":"ਬੀਰ ਬਡੇ ਇਹ ਕੀ ਦਿਸ ਕੇ ਰਿਸ ਸੋ ਜਦੁਬੀਰ ਕਉ ਮਾਰਨ ਧਾਏ।","roman":"Beer bade ih kee dis ke ris so jadubeer kau maaran dhaae |","meaning_en":"Great warriors of his side ran in anger to kill the Yadav hero.","page":647,"meaning_status":"draft"},{"gurmukhi":"ਜਾਤ ਕਹਾ ਫਿਰਿ ਸ੍ਯਾਮ ਲਰੋ ਹਮ ਸੋ ਸਭ ਹੀ ਇਹ ਭਾਤਿ ਬੁਲਾਏ।","roman":"Jaat kahaa phiri syaam laro ham so sabh hee ih bhaati bulaae |","meaning_en":"'Where are you going? Turn back, Shyam, and fight us,' they all called out thus.","page":647,"meaning_status":"draft"},{"gurmukhi":"ਤੇ ਬ੍ਰਿਜ ਨਾਥ ਹਨੇ ਸਭ ਹੀ ਕਹਿ ਕੈ ਉਪਮਾ ਕਬਿ ਸ੍ਯਾਮ ਸੁਨਾਏ।","roman":"Te brij naath hane sabh hee kahi kai upmaa kabi syaam sunaae |","meaning_en":"The Lord of Braj slew them all; poet Shyam tells the simile:","page":647,"meaning_status":"draft"},{"gurmukhi":"ਮਾਨਹੁ ਹੇਰਿ ਪਤੰਗ ਦੀਆ ਕਹੂ ਟੂਟਿ ਪਰੇ ਫਿਰਿ ਜੀਤ ਨ ਆਏ। ੨੦੦੧।","roman":"Maanhu heri patang deeaa kahoo tooti pare phiri jeet na aae | 2001 |","meaning_en":"like moths that see a lamp and fall upon it, and never come back alive.","page":647,"meaning_status":"draft","note":"ਜੀਤ: read as 'alive' (ਜੀਵਤ); uncertain."}]},{"type":"verse","number":[2002],"number_text":"੨੦੦੨।","page":647,"lines":[{"gurmukhi":"ਜਬ ਸੈਨ ਹਨਿਯੋ ਘਨ ਸ੍ਯਾਮ ਸਭੈ ਰੁਕਮੀ ਕੁਪ ਕੈ ਤਬ ਐਸੇ ਕਹਿਓ।","roman":"Jab sain haniyo ghan syaam sabhai rukmee kup kai tab aise kahio |","meaning_en":"When the cloud-dark one had slain the whole army, Rukmi in a rage then said thus:","page":647,"meaning_status":"draft"},{"gurmukhi":"ਜਬ ਗੂਜਰ ਹ੍ਵੈ ਧਨ ਬਾਨ ਗਹਿਯੋ ਛਤ੍ਰਾਪਨ ਛਤ੍ਰਿਨ ਤੇ ਤੋ ਰਹਿਓ।","roman":"Jab goojar hvai dhan baan gahiyo chhatraapan chhatrin te to rahio |","meaning_en":"'Now that a cowherd has taken up bow and arrows, warriorhood is gone from the Kshatriyas.'","page":647,"meaning_status":"draft","note":"ਛਤ੍ਰਾਪਨ ਛਤ੍ਰਿਨ ਤੇ ਤੋ ਰਹਿਓ: read as 'warriorhood has stayed behind / been lost by the Kshatriyas'; uncertain."},{"gurmukhi":"ਜਿਮ ਬੋਲਤ ਥੋ ਬਧ ਕੈ ਸਰ ਸ੍ਯਾਮ ਬਿਮੁੰਛਤ ਕੈ ਸੁ ਸਿਖਾ ਤੇ ਗਹਿਓ।","roman":"Jim bolat tho badh kai sar syaam bimunchhat kai su sikhaa te gahio |","meaning_en":"As he was speaking, Shyam struck him with arrows, made him faint, and seized him by the topknot.","page":647,"meaning_status":"draft"},{"gurmukhi":"ਗਹਿ ਕੈ ਤਿਹ ਮੂੰਡ ਕੋ ਮੂੰਡ ਦਯੋ ਉਪਹਾਸ ਕੈ ਜਿਉ ਚਿਤ ਬੀਚ ਚਹਿਓ। ੨੦੦੨।","roman":"Gahi kai tih moond ko moond dayo uphaas kai jiu chit beech chahio | 2002 |","meaning_en":"Holding him, he shaved his head, mocking him as his heart pleased.","page":647,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":647,"meaning_status":"draft"},{"type":"verse","number":[2003],"number_text":"੨੦੦੩।","page":647,"lines":[{"gurmukhi":"ਭ੍ਰਾਤ ਦਸਾ ਪਿਖਿ ਰੁਕਮਿਨੀ ਪ੍ਰਭ ਜੂ ਕੇ ਗਹਿ ਪਾਇ।","roman":"Bhraat dasaa pikhi rukminee prabh joo ke gahi paai |","meaning_en":"Seeing her brother's plight, Rukmini clasped the Lord's feet,","page":647,"meaning_status":"draft"},{"gurmukhi":"ਅਨਿਕ ਭਾਤਿ ਸੋ ਸ੍ਯਾਮ ਕਬਿ ਭ੍ਰਾਤ ਲਯੋ ਛੁਟਕਾਇ। ੨੦੦੩।","roman":"Anik bhaati so syaam kabi bhraat layo chhutkaai | 2003 |","meaning_en":"and with many pleas, says poet Shyam, got her brother released.","page":647,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":647,"meaning_status":"draft"},{"type":"verse","number":[2004],"number_text":"੨੦੦੪।","page":647,"lines":[{"gurmukhi":"ਜੋਊ ਤਾਹਿ ਸਹਾਇ ਕਉ ਆਵਤ ਭੇ ਸੁ ਹਨੇ ਸਭ ਹੀ ਚਿਤ ਮੈ ਚਹਿ ਕੈ।","roman":"Jo'oo taahi sahaai kau aavat bhe su hane sabh hee chit mai chahi kai |","meaning_en":"All who came to his aid he slew, as his mind wished.","page":647,"meaning_status":"draft"},{"gurmukhi":"ਜੋਊ ਸੂਰ ਹਨਿਯੋ ਨ ਹਨਿਯੋ ਛਲ ਸੋ ਅਰੇ ਮਾਰਤ ਹਉ ਤੁਹਿ ਯੌ ਕਹਿ ਕੈ।","roman":"Jo'oo soor haniyo na haniyo chhal so are maarat hau tuhi yau kahi kai |","meaning_en":"No warrior he slew was slain by deceit: he first said, 'Hey, I am going to kill you.'","page":647,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁ ਭੂਪ ਹਨੇ ਗਜਬਾਜ ਰਥੀ ਸਰਤਾ ਬਹੁ ਸ੍ਰੋਨ ਚਲੀ ਬਹਿ ਕੈ।","roman":"Bahu bhoop hane gajbaaj rathee sartaa bahu sron chalee bahi kai |","meaning_en":"Many kings, elephants, horses and charioteers were slain, and a river of blood flowed.","page":647,"meaning_status":"draft"},{"gurmukhi":"ਫਿਰਿ ਤ੍ਰੀਯ ਕੋ ਕਹੇ ਪੀਯ ਛੋਡ ਦਯੋ ਰੁਕਮੀ ਰਨਿ ਜੀਤਿ ਭਲੇ ਗਹਿ ਕੈ। ੨੦੦੪।","roman":"Phiri treey ko kahe peey chhod dayo rukmee rani jeeti bhale gahi kai | 2004 |","meaning_en":"Then at his wife's word the husband let Rukmi go, having defeated and captured him in battle.","page":647,"meaning_status":"draft"}]},{"type":"verse","number":[2005],"number_text":"੨੦੦੫।","page":647,"lines":[{"gurmukhi":"ਤਉ ਲਉ ਗਦਾ ਗਹਿ ਕੈ ਬਲਿਭਦ੍ਰ ਪਰਿਓ ਤਿਨ ਮੈ ਚਿਤਿ ਰੋਸ ਬਢਾਯੋ।","roman":"Tau lau gadaa gahi kai balibhadr pario tin mai chiti ros badhaayo |","meaning_en":"Meanwhile Balbhadra, mace in hand, fell upon them, his anger rising.","page":647,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰਨ ਸੈਨ ਭਜਿਯੋ ਜੋਊ ਜਾਤ ਹੋ ਸ੍ਯਾਮ ਭਨੈ ਸਭ ਕਉ ਮਿਲਿ ਘਾਯੋ।","roman":"Satran sain bhajiyo jo'oo jaat ho syaam bhanai sabh kau mili ghaayo |","meaning_en":"Of the enemy army that was fleeing, says Shyam, he caught and slew them all.","page":647,"meaning_status":"draft"},{"gurmukhi":"ਘਾਇ ਕੈ ਸੈਨ ਭਲੀ ਬਿਧਿ ਸੋ ਫਿਰਿ ਕੇ ਬ੍ਰਿਜ ਨਾਇਕ ਕੀ ਢਿਗ ਆਯੋ।","roman":"Ghaai kai sain bhalee bidhi so phiri ke brij naaik kee dhig aayo |","meaning_en":"Having destroyed the army thoroughly, he came back to the Lord of Braj.","page":647,"meaning_status":"draft"},{"gurmukhi":"ਸੀਸ ਮੁੰਡਿਓ ਰੁਕਮੀ ਕੋ ਸੁਨਿਯੋ ਜਬ ਤੋ ਹਰਿ ਸਿਉ ਇਹ ਬੈਨ ਸੁਨਾਯੋ। ੨੦੦੫।","roman":"Sees mundio rukmee ko suniyo jab to hari siu ih bain sunaayo | 2005 |","meaning_en":"When he heard that Rukmi's head had been shaved, he spoke these words to Hari.","page":647,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਬਲਭਦ੍ਰ ਬਾਚ ਕਾਨ੍ਹ ਜੂ ਸੋ","gurmukhi":"ਬਲਭਦ੍ਰ ਬਾਚ ਕਾਨ੍ਹ ਜੂ ਸੋ","roman":"Balbhadr baach kaanh joo so","meaning_en":"Balbhadra said to Krishna ji:","page":647,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":647,"meaning_status":"draft"},{"type":"verse","number":[2006],"number_text":"੨੦੦੬।","page":647,"lines":[{"gurmukhi":"ਭ੍ਰਾਤ ਤ੍ਰੀਆ ਕੋ ਰਨ ਬਿਖੈ ਕਾਨ੍ਹ ਜੀਤ ਜੋ ਲੀਨ।","roman":"Bhraat treeaa ko ran bikhai kaanh jeet jo leen |","meaning_en":"'Krishna, your wife's brother, whom you defeated in battle,","page":647,"meaning_status":"draft"},{"gurmukhi":"ਸੀਸ ਮੂੰਡ ਤਾ ਕੋ ਦਯੋ ਕਹਿਯੋ ਕਾਜ ਘਟ ਕੀਨ। ੨੦੦੬।","roman":"Sees moond taa ko dayo kahiyo kaaj ghat keen | 2006 |","meaning_en":"you have shaved his head; that was a poor deed,' he said.","page":647,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":648,"meaning_status":"draft"},{"type":"verse","number":[2007],"number_text":"੨੦੦੭।","page":648,"lines":[{"gurmukhi":"ਅਨਿ ਤੇ ਪੁਰ ਬਾਧਿ ਰਹੋ ਰੁਕਮੀ ਉਤ ਦ੍ਵਾਰਵਤੀ ਪ੍ਰਭ ਜੂ ਇਤ ਆਏ।","roman":"Ani te pur baadhi raho rukmee ut dvaaravtee prabh joo it aae |","meaning_en":"Rukmi built a city elsewhere and stayed there; here the Lord came to Dwarvati.","page":648,"meaning_status":"draft","note":"ਅਨਿ ਤੇ ਪੁਰ ਬਾਧਿ ਰਹੋ: read as 'built a city in another place and stayed'; uncertain."},{"gurmukhi":"ਆਇ ਹੈ ਕਾਨ੍ਹ ਜੂ ਜੀਤਿ ਤ੍ਰੀਆ ਸਭ ਯੌ ਸੁਨਿ ਕੈ ਜਨ ਦੇਖਨ ਧਾਏ।","roman":"Aai hai kaanh joo jeeti treeaa sabh yau suni kai jan dekhan dhaae |","meaning_en":"'Krishna ji is coming, having won a wife': hearing this, all the people ran to see.","page":648,"meaning_status":"draft"},{"gurmukhi":"ਬ੍ਯਾਹ ਕੇ ਕਾਜ ਕਉ ਜੇ ਥੇ ਦਿਜੋਤਮ ਤੇ ਸਭ ਹੀ ਮਿਲਿ ਕੈ ਸੁ ਬੁਲਾਏ।","roman":"Byaah ke kaaj kau je the dijotam te sabh hee mili kai su bulaae |","meaning_en":"All the excellent Brahmins needed for the wedding were called together,","page":648,"meaning_status":"draft"},{"gurmukhi":"ਅਉਰ ਜਿਤੋ ਬਲਵੰਤ ਬਡੇ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਸਭ ਬੋਲਿ ਪਠਾਏ। ੨੦੦੭।","roman":"Aur jito balvant bade kabi syaam kahai sabh boli pathaae | 2007 |","meaning_en":"and all the great and mighty men too, says poet Shyam, were sent for.","page":648,"meaning_status":"draft"}]},{"type":"verse","number":[2008],"number_text":"੨੦੦੮।","page":648,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕੋ ਬ੍ਯਾਹ ਸੁਨਿਯੋ ਪੁਰ ਨਾਰਿਨ ਆਵਤ ਭੀ ਸਭ ਹੀ ਮਿਲ ਗਾਵਤ।","roman":"Kaanh ko byaah suniyo pur naarin aavat bhee sabh hee mil gaavat |","meaning_en":"Hearing of Krishna's wedding, all the women of the city came, singing together.","page":648,"meaning_status":"draft"},{"gurmukhi":"ਨਾਚਤ ਡੋਲਤ ਭਾਤਿ ਭਲੀ ਕਬਿ ਸ੍ਯਾਮ ਭਨੈ ਮਿਲਿ ਤਾਲ ਬਜਾਵਤ।","roman":"Naachat dolat bhaati bhalee kabi syaam bhanai mili taal bajaavat |","meaning_en":"They danced and swayed beautifully, says poet Shyam, and kept time together.","page":648,"meaning_status":"draft"},{"gurmukhi":"ਆਪਸਿ ਮੈ ਮਿਲਿ ਕੈ ਤਰੁਨੀ ਸਭ ਖੇਲਨ ਕਉ ਅਤਿ ਹੀ ਠਟ ਪਾਵਤ।","roman":"Aapsi mai mili kai tarunee sabh khelan kau ati hee that paavat |","meaning_en":"All the young women, gathered together, made great preparations for merrymaking.","page":648,"meaning_status":"draft"},{"gurmukhi":"ਅਉਰ ਕੀ ਬਾਤ ਕਹਾ ਕਹੀਐ ਪਿਖਿਬੇ ਕਹੁ ਦੇਵ ਬਧੂ ਮਿਲਿ ਆਵਤ। ੨੦੦੮।","roman":"Aur kee baat kahaa kaheeai pikhibe kahu dev badhoo mili aavat | 2008 |","meaning_en":"What to say of others? Even the wives of the gods came together to watch.","page":648,"meaning_status":"draft"}]},{"type":"verse","number":[2009],"number_text":"੨੦੦੯।","page":648,"lines":[{"gurmukhi":"ਸੁੰਦਰਿ ਨਾਰਿ ਨਿਹਾਰਨ ਕਉ ਤਜਿ ਕੈ ਗ੍ਰਿਹ ਜੋ ਇਹ ਕਉਤੁਕ ਆਵੈ।","roman":"Sundri naari nihaaran kau taji kai grih jo ih kautuk aavai |","meaning_en":"Every lovely woman who left her home and came to see this spectacle","page":648,"meaning_status":"draft"},{"gurmukhi":"ਨਾਚਤ ਕੂਦਤ ਭਾਤਿ ਭਲੀ ਗ੍ਰਿਹ ਕੀ ਸੁਧਿ ਅਉਰ ਸਭੈ ਬਿਸਰਾਵੈ।","roman":"Naachat koodat bhaati bhalee grih kee sudhi aur sabhai bisraavai |","meaning_en":"danced and leapt finely, and forgot all thought of home and everything else.","page":648,"meaning_status":"draft"},{"gurmukhi":"ਦੇਖ ਕੈ ਬ੍ਯਾਹਹਿ ਕੀ ਰਚਨਾ ਸਭ ਹੀ ਅਪਨੋ ਮਨ ਮੈ ਸੁਖੁ ਪਾਵੈ।","roman":"Dekh kai byaahhi kee rachnaa sabh hee apno man mai sukhu paavai |","meaning_en":"Seeing the wedding arrangements, they all felt joy in their hearts.","page":648,"meaning_status":"draft"},{"gurmukhi":"ਐਸੇ ਕਹੈ ਬਲਿ ਜਾਹਿ ਸਭੈ ਜਬ ਕਾਨ੍ਹ ਕਉ ਦੇਖਿ ਸਭੈ ਲਲਚਾਵੈ। ੨੦੦੯।","roman":"Aise kahai bali jaahi sabhai jab kaanh kau dekhi sabhai lalchaavai | 2009 |","meaning_en":"All of them said, 'We would give our lives for him,' and all were charmed on seeing Krishna.","page":648,"meaning_status":"draft"}]},{"type":"verse","number":[2010],"number_text":"੨੦੧੦।","page":648,"lines":[{"gurmukhi":"ਜਬ ਕਾਨ੍ਹ ਕੇ ਬ੍ਯਾਹ ਕਉ ਬੇਦੀ ਰਚੀ ਪੁਰ ਨਾਰਿ ਸਭੈ ਮਿਲ ਮੰਗਲ ਗਾਯੋ।","roman":"Jab kaanh ke byaah kau bedee rachee pur naari sabhai mil mangal gaayo |","meaning_en":"When the altar was built for Krishna's wedding, all the women of the city together sang auspicious songs.","page":648,"meaning_status":"draft"},{"gurmukhi":"ਨਾਚਤ ਭੇ ਨਟੂਆ ਤਿਹ ਠਉਰ ਮ੍ਰਿਦੰਗਨ ਤਾਲ ਭਲੀ ਬਿਧਿ ਦ੍ਯਾਯੋ।","roman":"Naachat bhe natooaa tih thaur mridangan taal bhalee bidhi dyaayo |","meaning_en":"Dancers danced in that place, and the beat was given finely on the mridang drums.","page":648,"meaning_status":"draft"},{"gurmukhi":"ਕੋਟਿ ਕਤੂਹਲ ਹੋਤ ਭਏ ਅਰੁ ਬੇਸਿਯਨ ਕੋ ਕਛੁ ਅੰਤ ਨ ਆਯੋ।","roman":"Koti katoohal hot bhae aru besiyan ko kachhu ant na aayo |","meaning_en":"Countless entertainments took place, and there was no end of dancing-girls.","page":648,"meaning_status":"draft","note":"ਬੇਸਿਯਨ: 'courtesans, dancing-girls'."},{"gurmukhi":"ਜੋ ਇਹ ਕਉਤੁਕ ਦੇਖਨ ਕਉ ਚਲਿ ਆਯੋ ਹੁਤੋ ਸਭ ਹੀ ਸੁਖੁ ਪਾਯੋ। ੨੦੧੦।","roman":"Jo ih kautuk dekhan kau chali aayo huto sabh hee sukhu paayo | 2010 |","meaning_en":"All who had come to see this spectacle were made happy.","page":648,"meaning_status":"draft"}]},{"type":"verse","number":[2011],"number_text":"੨੦੧੧।","page":648,"lines":[{"gurmukhi":"ਏਕ ਬਜਾਵਤ ਬੇਨੁ ਸਖੀ ਇਕ ਹਾਥਿ ਲੀਏ ਸਖੀ ਤਾਲ ਬਜਾਵੈ।","roman":"Ek bajaavat benu sakhee ik haathi lee'e sakhee taal bajaavai |","meaning_en":"One friend plays the flute; another friend, with cymbals in her hand, beats time.","page":648,"meaning_status":"draft"},{"gurmukhi":"ਨਾਚਤ ਏਕ ਭਲੀ ਬਿਧਿ ਸੁੰਦਰਿ ਸੁੰਦਰਿ ਏਕ ਭਲੀ ਬਿਧਿ ਗਾਵੈ।","roman":"Naachat ek bhalee bidhi sundri sundri ek bhalee bidhi gaavai |","meaning_en":"One beauty dances gracefully; another beauty sings finely.","page":648,"meaning_status":"draft"},{"gurmukhi":"ਝਾਜਰ ਏਕ ਮ੍ਰਿਦੰਗ ਕੇ ਬਾਜਤ ਆਏ ਭਲੇ ਇਕ ਹਾਵ ਦਿਖਾਵੈ।","roman":"Jhaajar ek mridang ke baajat aae bhale ik haav dikhaavai |","meaning_en":"Some come in, playing jhanjh and mridang; one shows charming gestures.","page":648,"meaning_status":"draft","note":"ਝਾਜਰ: taken as a kind of cymbal (jhanjh); could be anklet-bells; uncertain."},{"gurmukhi":"ਭਾਇ ਕਰੈ ਇਕ ਆਇ ਤਬੈ ਚਿਤ ਕੇ ਰਨਿਵਾਰਨ ਮੋਦ ਬਢਾਵੈ। ੨੦੧੧।","roman":"Bhaai karai ik aai tabai chit ke ranivaaran mod badhaavai | 2011 |","meaning_en":"Another then comes and acts out moods, increasing the delight in the hearts of the palace women.","page":648,"meaning_status":"draft","note":"ਰਨਿਵਾਰਨ: 'the women of the royal household'."}]},{"type":"verse","number":[2012],"number_text":"੨੦੧੨।","page":648,"lines":[{"gurmukhi":"ਬਾਰੁਨੀ ਕੇ ਰਸ ਸੰਗ ਛਕੇ ਜਹ ਬੈਠੇ ਹੈ ਕ੍ਰਿਸਨ ਹੁਲਾਸ ਬਢੈ ਕੈ ।","roman":"Baarunee ke ras sang chhake jah baithe hai krisan hulaas badhai kai |","meaning_en":"Where Krishna sits with rising joy, sated with the pleasure of wine,","page":648,"meaning_status":"draft","note":"ਬਾਰੁਨੀ: wine (Varuni)."},{"gurmukhi":"ਕੁੰਕਮ ਰੰਗ ਰੰਗੇ ਪਟਵਾ ਭਟਵਾ ਅਪਨੇ ਅਤਿ ਆਨੰਦ ਕੈ ਕੈ।","roman":"Kunkam rang range patvaa bhatvaa apne ati aanand kai kai |","meaning_en":"his warriors sit in great delight, their garments dyed with saffron.","page":648,"meaning_status":"draft"},{"gurmukhi":"ਮੰਗਨ ਲੋਗਨ ਦੇਤ ਘਨੋ ਧਨ ਸ੍ਯਾਮ ਭਨੈ ਅਤਿ ਹੀ ਨਚਵੈ ਕੈ।","roman":"Mangan logan det ghano dhan syaam bhanai ati hee nachvai kai |","meaning_en":"He gives much wealth to those who ask, says Shyam, and has the dancers dance a great deal.","page":648,"meaning_status":"draft"},{"gurmukhi":"ਰੀਝਿ ਰਹੇ ਮਨ ਮੈ ਸਭ ਹੀ ਫੁਨਿ ਸ੍ਰੀ ਜਦੁਬੀਰ ਕੀ ਓਰਿ ਚਿਤੈ ਕੈ। ੨੦੧੨।","roman":"Reejhi rahe man mai sabh hee phuni sree jadubeer kee ori chitai kai | 2012 |","meaning_en":"All were charmed at heart as they gazed at the Yadav hero.","page":648,"meaning_status":"draft"}]},{"type":"verse","number":[2013],"number_text":"੨੦੧੩।","page":649,"lines":[{"gurmukhi":"ਬੇਦ ਕੇ ਬੀਚ ਲਿਖੀ ਬਿਧਿ ਜਿਉ ਜਦੁਬੀਰ ਬ੍ਯਾਹ ਤਿਹੀ ਬਿਧਿ ਕੀਨੋ।","roman":"Bed ke beech likhee bidhi jiu jadubeer byaah tihee bidhi keeno |","meaning_en":"As the rite is written in the Vedas, by that rite the Yadav hero performed the marriage","page":649,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਰੁਕਮੀ ਤੇ ਭਲੀ ਬਿਧਿ ਕੈ ਰੁਕਮਿਨਹਿ ਕੋ ਪੁਨਿ ਜੀਤ ਕੈ ਲੀਨੋ।","roman":"Jo rukmee te bhalee bidhi kai rukminhi ko puni jeet kai leeno |","meaning_en":"with Rukmini, whom he had won fairly from Rukmi.","page":649,"meaning_status":"draft"},{"gurmukhi":"ਜੀਤਹਿ ਕੀ ਬਤੀਆ ਸੁਨਿ ਕੈ ਅਤਿ ਭੀਤਰ ਮੋਦ ਬਢਿਓ ਪੁਰ ਤੀਨੋ।","roman":"Jeethi kee bateeaa suni kai ati bheetar mod badhio pur teeno |","meaning_en":"Hearing the news of the victory, great joy grew within all three worlds.","page":649,"meaning_status":"draft","note":"ਪੁਰ ਤੀਨੋ: 'the three cities / worlds'."},{"gurmukhi":"ਸ੍ਯਾਮ ਭਨੈ ਇਹ ਕਉਤਕ ਕੈ ਸਭ ਹੀ ਜਦੁਬੀਰਨ ਕਉ ਸੁਖ ਦੀਨੋ। ੨੦੧੩।","roman":"Syaam bhanai ih kautak kai sabh hee jadubeeran kau sukh deeno | 2013 |","meaning_en":"Shyam says, by this feat he gave happiness to all the Yadav heroes.","page":649,"meaning_status":"draft"}]},{"type":"verse","number":[2014],"number_text":"੨੦੧੪।","page":649,"lines":[{"gurmukhi":"ਸੁਖ ਮਾਨ ਕੈ ਮਾਇ ਪੀਯੋ ਜਲ ਵਾਰ ਕੈ ਅਉ ਦ੍ਵਿਜ ਲੋਕਨ ਦਾਨ ਦੀਓ ਹੈ।","roman":"Sukh maan kai maai peeyo jal vaar kai au dvij lokan daan deeo hai |","meaning_en":"Rejoicing, his mother waved water over him and drank it, and gave gifts to the Brahmins.","page":649,"meaning_status":"draft","note":"ਜਲ ਵਾਰ ਕੈ ਪੀਯੋ: the custom of waving water over a loved one and drinking it, taking on any harm."},{"gurmukhi":"ਐਸੇ ਕਹਿਯੋ ਸਭ ਹੀ ਭੂਅ ਕੋ ਸੁਖ ਆਜ ਸਭੈ ਹਮ ਲੂਟਿ ਲੀਓ ਹੈ।","roman":"Aise kahiyo sabh hee bhooa ko sukh aaj sabhai ham looti leeo hai |","meaning_en":"She said thus: 'Today we have carried off all the happiness of the earth.'","page":649,"meaning_status":"draft"},{"gurmukhi":"ਆਜ ਹੁਲਾਸ ਭਯੋ ਸਜਨੀ ਉਮਗਿਓ ਨ ਰਹੈ ਕਹਿਓ ਮੋਰ ਹੀਓ ਹੈ।","roman":"Aaj hulaas bhayo sajnee umgio na rahai kahio mor heeo hai |","meaning_en":"'Today there is rejoicing, friend; my heart is overflowing and cannot be held,' she said.","page":649,"meaning_status":"draft"},{"gurmukhi":"ਆਜ ਕੇ ਦਿਵਸ ਹੂੰ ਪੈ ਬਲਿ ਜਾਉ ਅਰੀ ਜਬ ਮੋ ਸੁਤ ਬ੍ਯਾਹ ਕੀਓ ਹੈ। ੨੦੧੪।","roman":"Aaj ke divas hoon pai bali jaau aree jab mo sut byaah keeo hai | 2014 |","meaning_en":"'I offer myself to this day, friend, on which my son has married.'","page":649,"meaning_status":"draft"}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਦਸਮ ਸਕੰਧੇ ਬਚਿਤ੍ਰ ਨਾਟਕੇ ਕ੍ਰਿਸਨਾਵਤਾਰੇ ਰੁਕਮਿਨੀ","roman":"Iti sree dasam sakandhe bachitr naatke krisnaavtaare rukminee","meaning_en":"Here ends, in Krishna avatar in the Bachitra Natak, (based on) the Tenth Skandh,","page":649,"meaning_status":"draft"},{"gurmukhi":"ਹਰਨ ਇਤ ਬ੍ਯਾਹ ਕਰਨ ਬਰਨਨੰ ਧਿਆਇ ਸਮਾਪਤੰ।","roman":"Haran it byaah karan barannan dhiaai samaaptan |","meaning_en":"the chapter describing the carrying off of Rukmini and then the wedding.","page":649,"meaning_status":"draft"}],"page":649}});
